from produire import produire,paras,table,steps
from medicaments import canesten
parts=[
('L’otomycose est une infection fongique du conduit auditif. Les {repères diagnostiques} la distinguent d’une otite bactérienne et d’une dermatite. Un prurit avec débris évocateurs oriente sans suffire seul.',paras('Des levures ou moisissures peuvent proliférer dans le conduit. L’écoulement, la plénitude et la baisse auditive sont variables.', 'La forme superficielle ne doit pas être confondue avec une infection fongique invasive chez un patient à risque. Une douleur profonde ou un déficit neurologique change l’urgence.')),
('Les {facteurs favorisants} comprennent humidité et traitements locaux prolongés. Diabète et immunodépression nécessitent une vigilance particulière. Une récidive demande de rechercher la cause persistante.',paras('Une flore modifiée après antibiotiques ou corticoïdes locaux peut favoriser la prolifération fongique. Baignade, instrumentation et obstacles du conduit peuvent contribuer.', 'Les HUG et les recommandations européennes décrivent Aspergillus et Candida parmi les agents possibles. Les proportions de séries locales ne sont pas transposées à la population suisse.')),
('La {prolifération superficielle} produit débris et inflammation. Le prurit favorise ensuite le grattage et les microtraumatismes. L’obstruction peut gêner le traitement et l’audition.',paras('Les filaments, spores et débris peuvent retenir l’humidité. Une levure peut produire un matériel blanchâtre tandis que certaines moisissures donnent des points sombres, mais l’aspect n’identifie pas toujours l’agent.', 'Une surinfection bactérienne ou une dermatite peut coexister. L’examen après nettoyage aide à distinguer les composantes.')),
('Les {signes de gravité} imposent de sortir du cadre d’une mycose simple. Douleur intense profonde, déficit facial ou altération générale demandent un avis urgent. Le terrain immunodéprimé renforce cette vigilance.',paras('Une otite nécrosante peut être liée à des bactéries ou à des champignons. La présence de débris fongiques ne garantit pas une atteinte limitée à la peau.', 'Rechercher granulations, extension au pavillon ou au visage, vertige important et baisse auditive soudaine. Un symptôme sévère résistant au traitement nécessite réévaluation spécialisée.')),
('L’{interrogatoire} précise prurit, humidité et produits utilisés. Il recherche une perforation ou une opération antérieure. Les traitements antibiotiques répétés sont particulièrement importants.',paras('Demander début, récidives, douleur, plénitude, baisse auditive et écoulement. Identifier gouttes, durée d’utilisation, appareil auditif, grattage et baignades.', 'Rechercher diabète, immunodépression, dermatose et allergie. Une amélioration incomplète sous antibiotiques doit faire revoir la cause plutôt que prolonger automatiquement.')),
('L’{examen} décrit les débris et l’inflammation du conduit. Il doit préciser l’état du tympan. Un nettoyage professionnel est souvent nécessaire pour examiner et traiter.',paras('L’otoscopie ou l’otomicroscopie recherche matériel duveteux, filaments, points noirs ou blancs, œdème et peau inflammatoire. L’aspect suggère mais ne remplace pas toujours un prélèvement.', 'Retirer les débris sous contrôle plutôt que laver à l’aveugle. Rechercher lésion focale, granulation et atteinte moyenne associée.')),
('Les {alternatives} comprennent infection bactérienne et dermatite. Certaines réactions aux gouttes ressemblent à une persistance infectieuse. Une maladie moyenne peut aussi entretenir l’écoulement.',table(['Alternative','Indice'],[['Otite externe bactérienne.','Douleur et inflammation, parfois sans débris fongiques.'],['Dermatite ou allergie.','Suintement, desquamation et lien avec une exposition.'],['Otite moyenne chronique.','Perforation ancienne et sécrétion d’origine moyenne.'],['Corps étranger.','Obstacle ou matériel retenu.'],['Otite nécrosante.','Douleur profonde et terrain à risque, granulation ou déficit.']])) ,
('Le {diagnostic} repose sur un ensemble clinique. La visualisation de débris compatibles est utile. Une culture isolée doit être interprétée avec l’examen.',paras('Un tableau de prurit, obstruction et matériel fongique soutient une otomycose. Un prélèvement avec examen mycologique et culture aide dans les formes persistantes, atypiques ou à risque.', 'Une absence de réponse oblige à vérifier diagnostic, nettoyage, accès du produit et facteurs favorisants. Ne pas assimiler toute sécrétion blanchâtre à Candida.')),
('Le {bilan} est ciblé. Il recherche l’agent et les complications lorsque la présentation le justifie. Une imagerie n’est pas requise dans toute mycose superficielle.',paras('Prélèvement bactérien et fongique si persistance, récidive, atteinte sévère ou immunodépression. Rechercher un diabète mal contrôlé ou une immunodépression selon le contexte.', 'En cas de suspicion d’invasion, l’ORL et l’infectiologue organisent imagerie et prélèvements tissulaires. Un résultat microbiologique ne doit pas retarder l’orientation urgente.')),
('L’{algorithme} associe nettoyage, sécurité tympanique et antifongique adapté. Le suivi vérifie l’élimination des débris. Une réaction locale impose une nouvelle évaluation.',steps('Rechercher signes d’invasion ou de complication et orienter en urgence si présents.', 'Examiner et nettoyer sous contrôle ; préciser si le tympan est intact.', 'Choisir la formulation adaptée ; la méthode Canesten Crème décrite dans l’AIPS concerne un tympan intact.', 'Organiser le contrôle et la gestion de la mèche lorsqu’elle est utilisée.', 'À l’échec, vérifier mycologie, allergie, maladie moyenne et terrain plutôt que multiplier les produits.')),
('Les {modalités suisses} incluent une méthode auriculaire avec Canesten Crème sur tympan intact. La formulation et le suivi de la mèche sont essentiels. Une prescription de spray cutané ne s’y substitue pas.',paras('@@MEDICAMENTS@@')+paras('Le nettoyage réduit les débris et améliore l’accès au site atteint. Corriger les facteurs favorisants et interrompre les traitements inutiles après réévaluation médicale.', 'En cas de perforation ou d’incertitude tympanique, demander un choix spécialisé compatible avec l’oreille moyenne. Ne pas instiller de préparation alcoolisée ou acidifiante à l’aveugle.', 'Une infection invasive nécessite traitement systémique individualisé et prise en charge multidisciplinaire ; un traitement local seul est insuffisant.')),
('La {prévention} limite humidité, grattage et traitements inutiles. Les dispositifs auditifs doivent être entretenus. Une récidive n’autorise pas automatiquement à reprendre l’ancien produit.',paras('Éviter cotons-tiges et produits domestiques. Garder l’oreille au sec selon les consignes et faire contrôler les facteurs mécaniques ou cutanés.', 'Respecter les rendez-vous de suivi de la mèche. Signaler douleur nouvelle, vertige, réaction cutanée ou baisse auditive.')),
('Le prurit et les débris fongiques orientent vers une otomycose. Le nettoyage et l’état du tympan guident le traitement. Canesten Crème a une méthode auriculaire suisse pour tympan intact. Une douleur profonde chez un patient à risque impose d’exclure une infection invasive.','')]
quiz=[('Le prurit prouve-t-il une mycose ?','Non : dermatite et allergie sont aussi possibles.'),('Les antibiotiques locaux prolongés peuvent-ils favoriser une otomycose ?','Oui, en modifiant la flore.'),('Les points noirs identifient-ils toujours une espèce ?','Non : l’aspect seul a des limites.'),('Une mycose peut-elle coexister avec une infection bactérienne ?','Oui.'),('Pourquoi nettoyer le conduit ?','Pour examiner et permettre l’accès au traitement.'),('L’état du tympan est-il secondaire ?','Non : il conditionne la sécurité du produit.'),('Une douleur profonde chez un immunodéprimé est-elle rassurante ?','Non : rechercher une atteinte invasive.'),('Quel prélèvement peut aider à l’échec ?','Un prélèvement bactérien et fongique interprété avec la clinique.'),('Quelle forme de Canesten est décrite pour une mèche auriculaire ?','La crème.'),('Quelle condition tympanique l’AIPS exige-t-elle ?','Un tympan intact.'),('Le spray est-il interchangeable dans le conduit ?','Non : sa formulation et son usage diffèrent.'),('L’AIPS donne-t-elle une fréquence spécifique de remplacement de cette mèche ?','Non : le professionnel doit organiser ce schéma et le suivi.'),('La crème est-elle en automédication chez les moins de deux ans ?','Non : l’AIPS exige une prescription médicale.'),('Que faire si une réaction cutanée apparaît ?','Arrêter et demander une réévaluation ; ne pas remplacer soi-même par le spray.')]
produire(5,parts,quiz,(3,7,21,23,27),canesten)
